rule joined_mnemonic_json_post {
  strings:
    $join = /\b[A-Za-z_][A-Za-z0-9_]{0,63}\s*=\s*[A-Za-z_][A-Za-z0-9_]{0,63}\.join\(\s*["'] ["']\s*\)/
    $post = /\bfetch\s*\([^;]{0,500}\bmethod\s*:\s*["']POST["'][^;]{0,500}\bbody\s*:\s*JSON\.stringify\(\s*\{\s*(seedPhrase|mnemonic)\s*:\s*[A-Za-z_][A-Za-z0-9_]{0,63}/
  condition:
    all of them and
    for any j in (1..#join) : (
      for any p in (1..#post) : (
        @post[p] > @join[j] and @post[p] - @join[j] < 4096 and
        for any n in (1..64) : (
          (uint8(@join[j]+n) <= 32 or uint8(@join[j]+n) == 61) and
          (uint8(@post[p]+!post[p]-n-1) <= 32 or
           uint8(@post[p]+!post[p]-n-1) == 58) and
          for all b in (0..n-1) : (
            uint8(@join[j]+b) == uint8(@post[p]+!post[p]-n+b)
          )
        )
      )
    )
}

rule queued_key_buffer_json_post {
  strings:
    $queue = /\b[A-Za-z_][A-Za-z0-9_]{0,63}\.push\(\s*\{[^}]{0,200}:\s*(e|ev|evt|event)\.key\b/
    $post = /\bfetch\s*\([^;]{0,500}\bmethod\s*:\s*["']POST["'][^;]{0,500}\bbody\s*:\s*JSON\.stringify\(\s*\{[^;]{0,300}\.splice\(\s*0\s*\)/
    $splice = /\b[A-Za-z_][A-Za-z0-9_]{0,63}\.splice\(\s*0\s*\)/
  condition:
    all of them and
    for any q in (1..#queue) : (
      for any p in (1..#post) : (
        for any s in (1..#splice) : (
          @splice[s] > @post[p] and
          @splice[s] + !splice[s] == @post[p] + !post[p] and
          for any n in (1..64) : (
            uint8(@queue[q]+n) == 46 and uint8(@splice[s]+n) == 46 and
            for all b in (0..n-1) : (
              uint8(@queue[q]+b) == uint8(@splice[s]+b)
            )
          )
        )
      )
    )
}

rule batch_command_output_curl_upload {
  strings:
    $capture = /(^|[\r\n])[ \t]*@?cmd(\.exe)?[ \t]+\/c[^\r\n>]{1,200}>[ \t]*"?/ nocase
    $upload = /(^|[\r\n])[ \t]*@?curl(\.exe)?[^\r\n]{0,200}--data-binary[ \t]+@"?/ nocase
    $path = /(%[a-z0-9_]{1,40}%|[a-z]:)\\[a-z0-9_.\\-]{1,160}/ nocase
  condition:
    #capture > 0 and #upload > 0 and #path <= 128 and
    for any p in (1..#path) : (
      for any c in (1..#capture) : (@path[p] == @capture[c] + !capture[c]) and
      for any q in (1..#path) : (
        @path[q] > @path[p] and @path[q] - @path[p] < 512 and
        !path[p] == !path[q] and
        for any u in (1..#upload) : (@path[q] == @upload[u] + !upload[u]) and
        for all k in (0..!path[p]-1) : (
          uint8(@path[p]+k) == uint8(@path[q]+k)
        )
      )
    )
}

import "pe"
rule resolve_net_user_add_global {
  strings:
    $api = "NetUserAdd\x00" ascii
    // push API name; push DLL name; LoadLibrary; push its handle;
    // GetProcAddress; store the resulting function pointer; return.
    $resolve = { 68 ?? ?? ?? ?? 68 ?? ?? ?? ?? FF 15 ?? ?? ?? ??
                 50 FF 15 ?? ?? ?? ?? A3 ?? ?? ?? ?? C3 }
  condition:
    pe.machine == pe.MACHINE_I386 and
    for any s in (0..pe.number_of_sections-1) : (
      pe.sections[s].name == ".text" and
      for any r in (1..#resolve) : (
        @resolve[r] >= pe.sections[s].raw_data_offset and
        @resolve[r] + !resolve[r] <= pe.sections[s].raw_data_offset + pe.sections[s].raw_data_size and
        uint32(@resolve[r]+19) == pe.image_base + pe.import_rva("KERNEL32.dll", "GetProcAddress") and
        (uint32(@resolve[r]+12) == pe.image_base + pe.import_rva("KERNEL32.dll", "LoadLibraryW") or
         uint32(@resolve[r]+12) == pe.image_base + pe.import_rva("KERNEL32.dll", "LoadLibraryA")) and
        for any a in (1..#api) : (
          pe.rva_to_offset(uint32(@resolve[r]+1)-pe.image_base) == @api[a]
        )
      )
    )
}
